def IM(name, h=190): return FIG(name).replace('<img class="fig"', f'<img style="height: {h}px; border-radius: 12px; border: 3px solid #D5DEEA; vertical-align: middle; margin-inline-start: 24px"')
def SV(svg, h=300): return svg.replace('<svg class="svgfig', f'<svg style="height: {h}px; width: auto; vertical-align: middle" class="svgfig')
def K(t): return f'<b style="color: #C2410C">{t}</b>'
import math as _mm
def RAYS(dirs, labs, size=400, closed=True):
    # أشعّةٌ من نقطةٍ واحدة باتجاهات dirs (بالدرجات، عكس عقارب الساعة)، و labs: تسمية كل زاويةٍ بين شعاعٍ والذي يليه
    c = size / 2; L = size * .42; out = []
    def pt(a, r): return c + r * _mm.cos(_mm.radians(a)), c - r * _mm.sin(_mm.radians(a))
    cols = ['#2563EB', '#DB2777', '#16A34A', '#F59E0B']
    if not closed: dirs = list(dirs)
    for k, (a0, lab) in enumerate(zip(dirs, labs)):
        if not closed and k == len(dirs) - 1: break
        a1 = dirs[(k + 1) % len(dirs)] + (360 if k == len(dirs) - 1 else 0); r = size * (.13 if k < len(dirs) - 1 else .09); col = cols[k % 4]
        p0, p1 = pt(a0, r), pt(a1, r)
        out.append(f'<path d="M{c},{c} L{p0[0]:.1f},{p0[1]:.1f} A{r},{r} 0 {1 if a1 - a0 > 180 else 0} 0 {p1[0]:.1f},{p1[1]:.1f} Z" fill="{col}22" stroke="{col}" stroke-width="4"/>')
        t = pt((a0 + a1) / 2, size * .3)
        out.append(f'<text x="{t[0]:.1f}" y="{t[1] + 12:.1f}" text-anchor="middle" direction="rtl" font-size="{size * .1:.0f}" font-weight="800" fill="{col}" font-family="Readex Pro,Tahoma,sans-serif">{lab}</text>')
    for a in dirs:
        q = pt(a, L); out.append(f'<line x1="{c}" y1="{c}" x2="{q[0]:.1f}" y2="{q[1]:.1f}" stroke="#14305C" stroke-width="5" stroke-linecap="round"/>')
    vh = size * .6 if not closed and max(dirs) <= 180 else size
    return f'<svg class="svgfig ang" viewBox="0 0 {size} {vh:.0f}" width="{size}" height="{vh:.0f}" xmlns="http://www.w3.org/2000/svg">' + ''.join(out) + '</svg>'
def TRI(labs=('', '', ''), size=420, cols=('#2563EB', '#DB2777', '#16A34A')):
    # مثلثٌ بزواياه الثلاث ملوّنة ومسمّاة: labs بالترتيب (اليسرى، اليمنى، العليا)
    P = [(size * .08, size * .62), (size * .92, size * .62), (size * .38, size * .08)]; out = []
    out.append('<polygon points="' + ' '.join(f'{x:.1f},{y:.1f}' for x, y in P) + '" fill="none" stroke="#14305C" stroke-width="5" stroke-linejoin="round"/>')
    for i, (lab, col) in enumerate(zip(labs, cols)):
        v = P[i]; u, w = P[(i + 1) % 3], P[(i + 2) % 3]; r = size * .1
        def d(q): L = _mm.hypot(q[0] - v[0], q[1] - v[1]); return (q[0] - v[0]) / L, (q[1] - v[1]) / L
        (ux, uy), (wx, wy) = d(u), d(w)
        p1 = (v[0] + r * ux, v[1] + r * uy); p2 = (v[0] + r * wx, v[1] + r * wy)
        sw = 1 if (ux * wy - uy * wx) > 0 else 0
        out.append(f'<path d="M{v[0]:.1f},{v[1]:.1f} L{p1[0]:.1f},{p1[1]:.1f} A{r},{r} 0 0 {sw} {p2[0]:.1f},{p2[1]:.1f} Z" fill="{col}33" stroke="{col}" stroke-width="4"/>')
        bx, by = ux + wx, uy + wy; bl = _mm.hypot(bx, by); t = (v[0] + size * .2 * bx / bl, v[1] + size * .2 * by / bl)
        if lab: out.append(f'<text x="{t[0]:.1f}" y="{t[1] + 11:.1f}" text-anchor="middle" direction="rtl" font-size="{size * .075:.0f}" font-weight="800" fill="{col}" font-family="Readex Pro,Tahoma,sans-serif">{lab}</text>')
    return f'<svg class="svgfig ang" viewBox="0 0 {size} {size * .7:.0f}" width="{size}" height="{size * .7:.0f}" xmlns="http://www.w3.org/2000/svg">' + ''.join(out) + '</svg>'
def TL(*t): return '<span style="display: inline-flex; gap: 56px; align-items: flex-end">' + ''.join(f'<span style="display: inline-flex; flex-direction: column; align-items: center; gap: 6px">{f}<span style="font-size: 34px; color: #3B5480">{c}</span></span>' for f, c in t) + '</span>'
def IMC(name, h, t):   # صورة الكتاب مع قصّ جزءٍ من أعلاها (نصٌّ زائد في القصاصة)
    return f'<span style="display: inline-block; height: {h}px; overflow: hidden; border-radius: 12px; border: 3px solid #D5DEEA; vertical-align: middle">' + FIG(name).replace('<img class="fig"', f'<img style="height: {h / (1 - t):.0f}px; margin-top: -{h * t / (1 - t):.0f}px; display: block"') + '</span>'
def W(t): return f'<span style="font-size: .8em; color: #3B5480">{t}</span>'   # سبب الخطوة
